css:
/* RHUMB LINE: the navigator's chart table.
   One idea: the app is a sea chart and a conversation is a plotted course.
   Messages hang off one dashed course line (character = fix circle, you = estimated-position square),
   the message box is a parallel rule, Home widgets / Ctrl+K / dialogs are chart insets framed by the
   graduated neatline, sidebars carry a latitude scale on their inner edge, the top bar is the top neatline.
   Day: printed chart in daylight. Night: the same chart under the red night-navigation lamp. */

:root {
  --mari-tokens-version: 1;
  --rl-serif: "Rhumb Serif", "Caladea", "Cambria", Georgia, serif;
  --rl-title: "Rhumb Title", "Rhumb Serif", Georgia, serif;
  --rl-log: "Rhumb Log", "Share Tech Mono", ui-monospace, monospace;

  --radius: 0px;
  --mari-font-ui: var(--rl-serif);
  --mari-font-heading: var(--rl-title);
  --mari-font-chat: var(--rl-serif);
  --ov-serif: var(--rl-title);
  --mari-chat-font-size: 17px;
  --mari-chat-line-height: 1.62;
  --mari-message-measure: 66ch;
  --mari-chat-column: 54rem;
  --mari-paragraph-gap: 0.8em;
  --mari-dialogue-weight: 400;
  --mari-text-outline: 0;
  --mari-min-ui-text: 12px;
  --mari-toast-font-size: 0.95rem;
  --mari-selected-tint: var(--primary);
  --mari-pinned-speaker: on;
  --mari-phone-avatar: hidden;
  --marinara-theme-accent-pulse: none;
  --glow-primary: transparent;
  --glow-accent: transparent;
  --mari-art-saturation-1: 22%;
  --mari-art-saturation-2: 18%;
  --mari-msg-head-rule: none;
  --mari-composer-placeholder: "Lay the next leg...";
  --mari-chat-row-art-opacity: 0;

  /* top bar = top neatline of the chart */
  --mari-top-bar-plate: transparent;
  --mari-top-bar-plate-radius: 0;
  --mari-top-bar-bg:
    repeating-linear-gradient(90deg, var(--rl-ink) 0 28px, transparent 28px 56px) left bottom 1px / 100% 4px no-repeat,
    linear-gradient(var(--rl-ink), var(--rl-ink)) left bottom / 100% 1px no-repeat,
    linear-gradient(var(--rl-ink), var(--rl-ink)) left bottom 6px / 100% 1px no-repeat,
    var(--rl-paper-solid);

  /* Home */
  --mari-home-art: none;
  --mari-home-wash: transparent;
  --mari-home-widget-radius: 0;
  --mari-home-widget-border-width: 8px;
  --mari-home-widget-font: var(--rl-serif);
  --mari-home-widget-title-font: var(--rl-title);
  --mari-home-widget-title-size: 1.45rem;
  --mari-home-widget-eyebrow-size: 0.72rem;
  --mari-home-widget-text-size: 0.95rem;
  --mari-home-widget-action-size: 0.9rem;
  --mari-home-shortcut-size: 0.95rem;
  --mari-home-shortcut-desc-size: 0.85rem;
  --mari-home-widget-glow: transparent;

  /* the chart, edge to edge; the reading column sits on its quiet middle band */
  --mari-app-backdrop-layers:
    var(--rl-chart) center / cover no-repeat,
    var(--rl-paper-solid);
  --mari-card-art-placeholder: var(--rl-rose) center / 64% auto no-repeat, linear-gradient(160deg, var(--rl-paper-deep), var(--rl-paper-solid));
  --mari-chat-wash: none;
  --mari-chat-header-bg: none;

  /* Weather: shared */
  --mari-weather-style: smooth;
  --mari-weather-rain-length: 1.4;
  --mari-weather-lightning-bolt: 2.4;
  --mari-weather-snow-shape: round;
  --mari-weather-snow-size: 0.9;
  --mari-weather-amount: 0.8;
  /* below deck at the chart table: no sun or moon in the sky over the chart */
  --mari-weather-sun: none;
  --mari-weather-moon: none;
}

/* ---------- DAY: printed chart in daylight ---------- */
:root[data-theme="light"] {
  --rl-paper: rgba(247, 243, 233, 0.9);
  --rl-paper-solid: #f4eedf;
  --rl-paper-deep: #ebe3cf;
  --rl-ink: #1d2b45;
  --rl-ink-soft: #46546b;
  --rl-text: #1b2338;
  --rl-mute: #4a5468;
  --rl-mark: #a52a6e; /* chart magenta */
  --rl-brass: #b08a3e;
  --rl-water: #d6e6ea;
  --rl-rule-bar: #221c18; /* ebony parallel rule */
  --rl-rule-text: #f1e8d8;
  --rl-frame: url("theme:neatline-day.png");
  --rl-frame-thin: url("theme:neatline-thin-day.png");

  --background: #f4eedf;
  --foreground: #1b2338;
  --card: rgba(247, 243, 233, 0.92);
  --card-foreground: #1b2338;
  --popover: #f7f3e9;
  --popover-foreground: #1b2338;
  --primary: #1f5c66;
  --primary-foreground: #ffffff;
  --mari-status-online: #5f7a2e;
  --mari-status-idle: #a8752a;
  --mari-status-dnd: #a52a6e;
  --mari-status-offline: #8a8676;
  --secondary: #e6ddc6;
  --secondary-foreground: #1b2338;
  --muted: #e9e1cc;
  --muted-foreground: #4a5468;
  --accent: #d6e6ea;
  --accent-foreground: #1b2338;
  --destructive: #b3261e;
  --destructive-foreground: #ffffff;
  --border: rgba(29, 43, 69, 0.35);
  --input: rgba(29, 43, 69, 0.4);
  --ring: #a52a6e;
  --sidebar: rgba(244, 238, 223, 0.94);
  --sidebar-foreground: #1b2338;
  --sidebar-border: #1d2b45;
  --sidebar-accent: rgba(165, 42, 110, 0.1);
  --sidebar-accent-foreground: #1b2338;
  --ov-line: rgba(29, 43, 69, 0.3);
  --ov-text: #1b2338;
  --ov-muted: #4a5468;
  --ov-dim: #5d6679;
  --ov-accent: #1f5c66;
  --mari-chrome-accent: #a52a6e;
  --mari-chrome-muted: #4a5468;
  --mari-message-time: #4a5468;
  --mari-message-actions: #46546b;
  --mari-swipe-counter: #46546b;
  --mari-dialogue-color: #24496f;
  --mari-mode-conversation: #1f5f7a;
  --mari-mode-roleplay: #a52a6e;
  --mari-mode-game: #7a5a14;
  --ov-mode-conversation: #1f5f7a;
  --ov-mode-roleplay: #a52a6e;
  --ov-mode-game: #7a5a14;
  --mari-home-pink: #a52a6e;
  --mari-home-violet: #1d2b45;
  --mari-home-widget-bg: transparent;
  --mari-home-widget-title-color: #1d2b45;
  --mari-home-widget-eyebrow-color: #a52a6e;
  --mari-home-widget-muted: #3f4a5e;
  --mari-page-veil: rgba(244, 238, 223, 0.86);
  --mari-scrim: rgba(29, 43, 69, 0.35);
  --rl-chart: url("theme:chart-day.webp");
  --rl-rose: url("theme:compass-rose.webp");
  --mari-stage-empty-bg: url("theme:compass-rose.webp") center / min(34%, 300px) auto no-repeat, linear-gradient(180deg, #e9f1f1, #d6e6ea);

  --mari-weather-rain-color: #3d5878;
  --mari-weather-snow-color: #ffffff;
  --mari-weather-fog-color: #b9c6cb;
  --mari-weather-dust-color: #8a7a52;
  --mari-weather-sun-color: #f2d27a;
  --mari-weather-lightning-color: #fffaf0;
  --mari-weather-tint-strength: 0.55;
  --mari-weather-strength: 1.2;
}

/* ---------- NIGHT: the chart under the red night lamp ---------- */
:root,
:root[data-theme="dark"] {
  --rl-paper: rgba(20, 16, 19, 0.88);
  --rl-paper-solid: #141114;
  --rl-paper-deep: #1d1719;
  --rl-ink: #b8483e;
  --rl-ink-soft: #8f4a44;
  --rl-text: #ecdcd0;
  --rl-mute: #c3a99d;
  --rl-mark: #e0685a;
  --rl-brass: #a8713a;
  --rl-water: #2a1a1c;
  --rl-rule-bar: #0b0909;
  --rl-rule-text: #ecdcd0;
  --rl-frame: url("theme:neatline-night.png");
  --rl-frame-thin: url("theme:neatline-thin-night.png");

  --background: #121014;
  --foreground: #ecdcd0;
  --card: rgba(22, 18, 22, 0.92);
  --card-foreground: #ecdcd0;
  --popover: #171215;
  --popover-foreground: #ecdcd0;
  --primary: #7a2a20;
  --primary-foreground: #f3dccd;
  --mari-status-online: #d9a35a;
  --mari-status-idle: #b8763a;
  --mari-status-dnd: #c8503e;
  --mari-status-offline: #6e5048;
  --mari-ctrlk-conversation: #d99a7a;
  --mari-ctrlk-roleplay: #e0685a;
  --mari-ctrlk-game: #d6a35a;
  --secondary: #261b1d;
  --secondary-foreground: #ecdcd0;
  --muted: #221a1c;
  --muted-foreground: #c3a99d;
  --accent: #2c1d1f;
  --accent-foreground: #ecdcd0;
  --destructive: #ff7a66;
  --destructive-foreground: #140c0c;
  --border: rgba(184, 72, 62, 0.42);
  --input: rgba(184, 72, 62, 0.5);
  --ring: #e0685a;
  --sidebar: rgba(18, 14, 17, 0.95);
  --sidebar-foreground: #ecdcd0;
  --sidebar-border: #b8483e;
  --sidebar-accent: rgba(208, 88, 76, 0.14);
  --sidebar-accent-foreground: #ecdcd0;
  --ov-line: rgba(184, 72, 62, 0.4);
  --ov-text: #ecdcd0;
  --ov-muted: #c3a99d;
  --ov-dim: #a88e84;
  --ov-accent: #e0685a;
  --mari-chrome-accent: #e0685a;
  --mari-chrome-muted: #c3a99d;
  --mari-message-time: #c3a99d;
  --mari-message-actions: #c3a99d;
  --mari-swipe-counter: #c3a99d;
  --mari-dialogue-color: #f3b7a4;
  --mari-mode-conversation: #d99a7a;
  --mari-mode-roleplay: #e0685a;
  --mari-mode-game: #d6a35a;
  --ov-mode-conversation: #d99a7a;
  --ov-mode-roleplay: #e0685a;
  --ov-mode-game: #d6a35a;
  --mari-home-pink: #e0685a;
  --mari-home-violet: #d99a7a;
  --mari-home-widget-bg: transparent;
  --mari-home-widget-title-color: #f1e2d6;
  --mari-home-widget-eyebrow-color: #e0685a;
  --mari-home-widget-muted: #c9b0a4;
  --mari-page-veil: rgba(18, 14, 17, 0.86);
  --mari-scrim: rgba(5, 3, 4, 0.6);
  --rl-chart: url("theme:chart-night.webp");
  --rl-rose: url("theme:compass-rose-night.webp");
  --mari-stage-empty-bg: url("theme:compass-rose-night.webp") center / min(34%, 300px) auto no-repeat, radial-gradient(ellipse at 70% 20%, #3a1a18, #120e10 70%);

  --mari-weather-rain-color: #d8aaa2;
  --mari-weather-snow-color: #e8d6d0;
  --mari-weather-fog-color: #6e5a5a;
  --mari-weather-dust-color: #c0705e;
  --mari-weather-star-color: #f0d6c8;
  --mari-weather-moon-color: #f3e2d2;
  --mari-weather-firefly-color: #e0685a;
  --mari-weather-lightning-color: #fff1e0;
  --mari-weather-tint-strength: 0.3;
  --mari-weather-strength: 1;
}

/* rain and storm: the chart gets wet */
:root[data-theme="light"][data-mari-weather="rain"],
:root[data-theme="light"][data-mari-weather="storm"] {
  --rl-chart: url("theme:chart-wet-day.webp");
}
:root[data-theme="dark"][data-mari-weather="rain"],
:root[data-theme="dark"][data-mari-weather="storm"] {
  --rl-chart: url("theme:chart-wet-night.webp");
}
:root[data-mari-weather="rain"],
:root[data-mari-weather="storm"] {
  --mari-weather-strength: 1.35;
}
/* the night storm is darker than a calm night: no milky wash, so the edge bolt is the brightest thing */
:root[data-theme="dark"][data-mari-weather="storm"],
:root[data-theme="dark"][data-mari-weather="rain"] {
  --mari-weather-tint-strength: 0;
  --mari-weather-rain-color: #8a5a4a;
}
/* phones: the portrait chart */
@media (max-width: 640px) {
  :root[data-theme="light"] { --rl-chart: url("theme:chart-phone-day.webp"); }
  :root[data-theme="dark"] { --rl-chart: url("theme:chart-phone-night.webp"); }
}
:root[data-mari-weather="fog"] {
  --mari-weather-tint-strength: 0.9;
  --mari-weather-strength: 1.5;
}

/* ---------- squared everything: charts have no rounded corners ---------- */
*,
*::before,
*::after {
  border-radius: 0;
}
[role="switch"],
[role="switch"] > span,
[data-mari-part="avatar-placeholder"],
.rounded-full[class*="bg-[var(--mari-status"],
span[class*="bg-[var(--mari-status"] {
  border-radius: 999px;
}

body {
  font-family: var(--rl-serif);
}

/* ---------- top bar: the top neatline ---------- */
[data-component="TopBar"] {
  color: var(--rl-ink);
}
[data-component="TopBar"] .ov-tab {
  font-family: var(--rl-serif);
  border: 1px solid transparent;
}
[data-component="TopBar"] .ov-tab.is-on {
  border-color: var(--rl-ink);
  background: var(--rl-paper-deep);
  box-shadow: inset 0 -3px 0 var(--rl-mark);
}

/* ---------- sidebars: chart margins with a latitude scale ---------- */
[data-component="ChatSidebar"] {
  background:
    linear-gradient(var(--rl-ink), var(--rl-ink)) right 9px top 0 / 1px 100% no-repeat,
    repeating-linear-gradient(180deg, var(--rl-ink) 0 1px, transparent 1px 80px) right 0 top 0 / 9px 100% no-repeat,
    repeating-linear-gradient(180deg, var(--rl-ink) 0 1px, transparent 1px 40px) right 0 top 0 / 6px 100% no-repeat,
    repeating-linear-gradient(180deg, var(--rl-ink) 0 1px, transparent 1px 8px) right 0 top 0 / 3px 100% no-repeat,
    var(--sidebar);
  border-right: 0;
  padding-right: 10px;
}
[data-component="RightPanelDesktop"] {
  background:
    linear-gradient(var(--rl-ink), var(--rl-ink)) left 9px top 0 / 1px 100% no-repeat,
    repeating-linear-gradient(180deg, var(--rl-ink) 0 1px, transparent 1px 80px) left 0 top 0 / 9px 100% no-repeat,
    repeating-linear-gradient(180deg, var(--rl-ink) 0 1px, transparent 1px 40px) left 0 top 0 / 6px 100% no-repeat,
    repeating-linear-gradient(180deg, var(--rl-ink) 0 1px, transparent 1px 8px) left 0 top 0 / 3px 100% no-repeat,
    var(--sidebar);
  border-left: 0;
  padding-left: 10px;
}
[data-chat-row][data-selected="true"] {
  background: var(--sidebar-accent);
  box-shadow: inset 0 0 0 1px var(--rl-ink);
}

/* ---------- messages: positions on a plotted course ---------- */
/* The row is a 5-column grid (gutter | avatar | body | avatar | gutter); the user's avatar normally
   takes column 4. On a course every position sits on the same line, so both go to column 2. */
.mari-roleplay-message-row {
  position: relative;
  margin-bottom: 0;
  padding-bottom: 1.5rem;
}
.mari-roleplay-message-row > [data-mari-part="avatar"] {
  grid-column: 2 !important;
  grid-row: 1;
  align-self: stretch;
  position: relative;
  z-index: 1;
}
.mari-roleplay-message-row > .mari-message-body {
  grid-column: 3 !important;
  grid-row: 1;
  align-items: flex-start !important;
}
/* the course line: hangs from each position down to the next one, so it runs unbroken */
.mari-roleplay-message-row > [data-mari-part="avatar"]::before {
  content: "";
  position: absolute;
  left: calc(50% - 1px);
  top: 0;
  bottom: -1.5rem;
  width: 2px;
  background: repeating-linear-gradient(180deg, var(--rl-ink) 0 9px, transparent 9px 15px);
  opacity: 0.8;
  pointer-events: none;
  z-index: -1;
}
/* the character: a fix (circle, dot, magenta ring) */
.mari-roleplay-message-row [data-mari-part="avatar"] button {
  border-radius: 999px;
  box-shadow:
    0 0 0 3px var(--rl-paper-solid),
    0 0 0 5px var(--rl-mark);
  --tw-ring-color: transparent;
}
/* you: an estimated position (square) */
.mari-roleplay-message-row.mari-message-user [data-mari-part="avatar"] button,
.mari-roleplay-message-row.mari-message-user [data-mari-part="avatar"] img {
  border-radius: 0;
}
.mari-roleplay-message-row.mari-message-user [data-mari-part="avatar"] button {
  box-shadow:
    0 0 0 3px var(--rl-paper-solid),
    0 0 0 5px var(--rl-ink);
}

.mari-rp-bubble {
  background: var(--rl-paper);
  color: var(--rl-text);
  border-radius: 0;
  box-shadow: none;
  --tw-ring-color: transparent;
  border-left: 2px solid var(--rl-ink);
}
.mari-rp-bubble--user {
  background: color-mix(in srgb, var(--rl-water) 70%, var(--rl-paper-solid));
  color: var(--rl-text);
  border-left-style: dashed;
}
.mari-rp-bubble .mari-message-content {
  color: var(--rl-text);
}
/* the log line: LEG 07 · NAME · time */
.mari-roleplay-message-row [data-mari-part="header"] {
  font-family: var(--rl-log);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-bottom: 1px solid var(--ov-line);
  padding-bottom: 0.3rem;
  margin-bottom: 0.5rem;
}
.mari-roleplay-message-row [data-mari-part="header"]::before {
  counter-reset: leg var(--mari-msg-index);
  content: "LEG " counter(leg, decimal-leading-zero);
  font-family: var(--rl-log);
  font-size: 0.8rem;
  color: var(--rl-mark);
  margin-right: 0.6rem;
}
.mari-roleplay-message-row .mari-message-name {
  font-family: var(--rl-log);
  font-size: 0.85rem;
  color: var(--rl-ink) !important;
  font-weight: 400;
}
.mari-roleplay-message-row [data-mari-part="time"] {
  font-family: var(--rl-log);
  font-size: 0.78rem;
  color: var(--mari-message-time);
}

/* ---------- composer: the parallel rule ---------- */
[data-mari-part="composer"] .mari-chat-input-box {
  border-radius: 0 !important;
  border-style: solid;
  border-color: transparent;
  border-width: 20px 26px 12px;
  border-image: url("theme:rule-bar.webp") 30 40 20 fill / 20px 26px 12px round;
  background: #1f1a17;
  background-clip: padding-box;
  color: var(--rl-rule-text);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.28);
  padding-top: 0.15rem;
  padding-bottom: 0.15rem;
}
[data-mari-part="composer"] textarea {
  color: var(--rl-rule-text);
  font-family: var(--rl-serif);
  font-size: 1rem;
}
[data-mari-part="composer"] textarea::placeholder {
  color: color-mix(in srgb, var(--rl-rule-text) 62%, transparent);
  font-style: italic;
}
[data-mari-part="composer"] button {
  color: color-mix(in srgb, var(--rl-rule-text) 80%, transparent);
}

/* ---------- Home widgets, Ctrl+K, dialogs: chart insets ---------- */
[data-mari-part="home-widget"] {
  border-style: solid;
  border-width: 8px;
  border-image: var(--rl-frame) 8 fill / 8px round;
  background: transparent;
  padding: 0.35rem;
}
[data-mari-part="home-widget-eyebrow"] {
  font-family: var(--rl-log);
  font-weight: 400;
  letter-spacing: 0.14em;
}
[data-mari-part="home-widget-title"] {
  font-weight: 400;
}
[role="dialog"],
.mari-window,
[data-component="GlobalOmnibar"] {
  border-radius: 0;
}
:root {
  --mari-focus-frame: var(--rl-frame-thin) 8 / 8px round;
  --mari-pinned-speaker-bg: var(--rl-paper-solid);
}

/* ---------- conversation: the same course, logged tighter ---------- */
[data-chat-mode="conversation"] [data-mari-part="message"] .mari-message {
  padding-top: 0.35rem;
  padding-bottom: 0.35rem;
}
[data-chat-mode="conversation"] [data-mari-part="message"] [data-mari-part="avatar"] {
  position: relative;
  max-height: none;
  align-items: center;
  justify-content: flex-start;
  padding-top: 0.2rem;
}
[data-chat-mode="conversation"] [data-mari-part="message"] [data-mari-part="avatar"]::before {
  content: "";
  position: absolute;
  left: calc(50% - 1px);
  top: -0.6rem;
  bottom: -0.9rem;
  width: 2px;
  background: repeating-linear-gradient(180deg, var(--rl-ink) 0 7px, transparent 7px 12px);
  opacity: 0.7;
  pointer-events: none;
}
[data-chat-mode="conversation"] [data-mari-part="message"] [data-mari-part="avatar"] button {
  position: relative;
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 999px;
  box-shadow:
    0 0 0 3px var(--rl-paper-solid),
    0 0 0 4.5px var(--rl-mark);
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] [data-mari-part="avatar"] button,
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] [data-mari-part="avatar"] img {
  border-radius: 0;
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] [data-mari-part="avatar"] button {
  box-shadow:
    0 0 0 3px var(--rl-paper-solid),
    0 0 0 4.5px var(--rl-ink);
}
[data-chat-mode="conversation"] .mari-message-name {
  font-family: var(--rl-log);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 400;
  font-size: 0.9rem;
  color: var(--rl-ink);
}
[data-chat-mode="conversation"] [data-mari-part="time"] {
  font-family: var(--rl-log);
  font-size: 0.78rem;
  color: var(--mari-message-time);
}
[data-chat-mode="conversation"] .mari-message-content {
  color: var(--rl-text);
}
[data-mari-part="chat-header"] {
  border-bottom: 1px solid var(--rl-ink);
}

/* the newest reply is the current position: it gets the neatline (focus frame). Make room for it. */
[data-chat-mode="conversation"] [data-mari-part="message"][data-latest] {
  border-style: solid;
  border-color: transparent;
  border-width: 8px;
  margin: 0.4rem 1.25rem 0.4rem 0;
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-latest] > .mari-message,
[data-chat-mode="conversation"] [data-mari-part="message"][data-latest] > .px-4 {
  padding-left: 0;
  padding-right: 0;
}
.mari-roleplay-message-row[data-latest] .mari-rp-bubble {
  border-style: solid;
  border-color: transparent;
  border-width: 8px;
}
.mari-roleplay-message-row[data-latest] .mari-rp-bubble > .px-4 {
  padding: 0.5rem 0.75rem 0.6rem;
}

/* the chart under the rule: a paper band so scrolled text doesn't show beneath the message box */
[data-mari-part="composer"] {
  background: linear-gradient(180deg, transparent, var(--rl-paper-solid) 38%);
}

/* ---------- game: the narration box is a chart inset, the map float a small inset ---------- */
[data-mari-part="message"][data-game-narration] {
  border-style: solid;
  border-color: transparent;
  border-width: 8px;
  border-image: var(--rl-frame) 8 fill / 8px round;
  background: transparent;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
  backdrop-filter: none;
  color: var(--rl-text);
  padding: 0.5rem 0.75rem 0.6rem;
}
[data-mari-part="message"][data-game-narration] > div:first-child > span {
  background: transparent;
  font-family: var(--rl-log);
  font-weight: 400;
  letter-spacing: 0.16em;
  color: var(--rl-mark);
  padding: 0;
  font-size: 0.75rem;
}
[data-mari-part="message"][data-game-narration] .game-narration-prose {
  background: transparent;
  border: 0;
  border-top: 1px solid var(--ov-line);
  border-bottom: 1px solid var(--ov-line);
  color: var(--rl-text);
  font-family: var(--rl-serif);
}
[data-mari-part="message"][data-game-narration] .game-narration-prose > div:first-child {
  font-size: 17px !important;
  line-height: 1.6;
}
[data-mari-part="game-tools"] button,
[data-mari-part="message"][data-game-narration] button {
  background: transparent;
  border-color: var(--ov-line);
  color: var(--rl-text);
}
[data-mari-part="game-hud"] .mari-game-narration-surface {
  border-style: solid;
  border-color: transparent;
  border-width: 8px;
  border-image: var(--rl-frame-thin) 8 fill / 8px round;
  background: transparent;
  backdrop-filter: none;
  color: var(--rl-text);
}
[data-mari-part="game-hud"] .mari-game-narration-surface span {
  color: var(--rl-mute);
  font-family: var(--rl-log);
  font-size: 0.75rem;
}
[data-mari-part="composer"][data-composer="game"] {
  --mari-composer-placeholder: "Give your orders...";
  background: transparent;
}
[data-mari-part="composer"][data-composer="conversation"] {
  --mari-composer-placeholder: "Signal the crew...";
}

/* ---------- phones: no avatar column, so the course line and the marks are drawn in the gutter ---------- */
@media (max-width: 640px) {
  .mari-roleplay-message-row {
    padding-left: 1.4rem !important;
  }
  .mari-roleplay-message-row::before {
    content: "";
    position: absolute;
    left: 0.55rem;
    top: 0;
    bottom: 0;
    width: 2px;
    background: repeating-linear-gradient(180deg, var(--rl-ink) 0 8px, transparent 8px 13px);
    opacity: 0.8;
    pointer-events: none;
  }
  .mari-roleplay-message-row::after {
    content: "";
    position: absolute;
    z-index: 2;
    top: 0.35rem;
    left: calc(0.55rem + 1px - 6.5px);
    width: 13px;
    height: 13px;
    box-sizing: border-box;
    border-radius: 999px;
    border: 2px solid var(--rl-mark);
    background: radial-gradient(circle, var(--rl-mark) 0 2px, var(--rl-paper-solid) 2.5px);
    pointer-events: none;
  }
  .mari-roleplay-message-row.mari-message-user::after {
    border-radius: 0;
    border-color: var(--rl-ink);
    background: radial-gradient(circle, var(--rl-ink) 0 2px, var(--rl-paper-solid) 2.5px);
  }
  .mari-roleplay-message-row [data-mari-part="header"][data-placement="outside"] {
    flex-direction: row !important;
    justify-content: flex-start !important;
    border-bottom: 0;
  }
  [data-mari-part="composer"] .mari-chat-input-box {
    border-width: 18px 14px 10px;
    border-image-width: 18px 14px 10px;
  }
}

/* ================= ROUND 2 ================= */

/* fix symbols on desktop: the portrait stays clean; the chart symbol sits on the course line just under it
   (a ring with a centre dot for a fix, a square with a centre dot for your estimated position) */
.mari-roleplay-message-row > [data-mari-part="avatar"] > div {
  position: relative;
  overflow: visible;
}
.mari-roleplay-message-row > [data-mari-part="avatar"] > div::after {
  content: "";
  position: absolute;
  left: 50%;
  top: calc(100% + 7px);
  width: 15px;
  height: 15px;
  transform: translateX(-50%);
  box-sizing: border-box;
  right: auto;
  bottom: auto;
  pointer-events: none;
  z-index: 2;
  filter: none;
  opacity: 1;
  animation: none;
  border: 2px solid var(--rl-mark);
  border-radius: 50%;
  background: radial-gradient(circle, var(--rl-mark) 0 2px, var(--rl-paper-solid) 2.5px);
}
.mari-roleplay-message-row.mari-message-user > [data-mari-part="avatar"] > div::after {
  border-color: var(--rl-ink);
  border-radius: 0;
  background: linear-gradient(var(--rl-ink), var(--rl-ink)) center / 4px 4px no-repeat, var(--rl-paper-solid);
}

/* the pinned log line: a taller solid plate, and a fade under it that, when the line is not pinned,
   only covers the gap above the first line of text */
.mari-roleplay-message-row .mari-rp-bubble [data-mari-part="header"] {
  margin-bottom: 1.2rem;
}
.mari-roleplay-message-row .mari-rp-bubble [data-mari-part="header"]::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: calc(100% + 1px);
  height: 1.15rem;
  background: linear-gradient(180deg, var(--mari-pinned-speaker-bg) 0 62%, transparent);
  pointer-events: none;
}

/* swipe and regenerate tools sit on a paper chip, never on the coastline art */
.ov-rpf--below {
  background: var(--rl-paper-solid);
  box-shadow: inset 0 0 0 1px var(--ov-line);
  padding: 0.1rem 0.35rem;
}

/* Home: the greeting belongs on a chart */
[data-component="CenterContent"] h1.font-black {
  position: relative;
  visibility: hidden;
}
[data-component="CenterContent"] h1.font-black::before {
  content: "Where are we bound tonight?";
  visibility: visible;
  position: absolute;
  left: 0;
  top: 0;
  white-space: nowrap;
  font-family: var(--rl-title);
  font-weight: 400;
  font-size: 0.9em;
}

/* "+ New": an outlined chart label, not a solid slab */
.ov-new-pill {
  background: transparent !important;
  color: var(--primary) !important;
  box-shadow: inset 0 0 0 1.5px var(--primary);
}
:root[data-theme="dark"] .ov-new-pill {
  color: var(--rl-mark) !important;
  box-shadow: inset 0 0 0 1px var(--rl-mark);
}

/* square switches: inked outline so off reads as off */
[role="switch"] {
  box-shadow: inset 0 0 0 1px var(--rl-ink);
}

/* pictures on the chart: library art and game scenes take the chart's ink by day */
[data-mari-part="card-art"] img,
[data-chat-mode="game"] div.bg-cover.inset-0 {
  filter: sepia(0.45) saturate(0.7) contrast(0.95);
}
[data-mari-part="game-hud"] .mari-game-narration-surface {
  background: var(--rl-rose) right -18px center / 84px auto no-repeat;
}
[data-mari-part="game-hud"] button {
  color: var(--rl-text) !important;
  border-color: var(--ov-line) !important;
  background: var(--rl-paper-solid) !important;
}
.anim-text-flicker {
  color: var(--rl-mark) !important;
}

/* night: red-lamp discipline. Every picture, avatar and icon is seen under the lamp, so it goes
   lamp-red and dim; nothing full-colour survives in the chartroom. */
:root[data-theme="dark"] img:not([data-mari-part="backdrop"]),
:root[data-theme="dark"] [data-mari-part="card-art"] img,
:root[data-theme="dark"] [data-chat-mode="game"] div.bg-cover.inset-0,
:root[data-theme="dark"] [data-mari-part="avatar-placeholder"] {
  filter: grayscale(1) sepia(1) saturate(2.2) hue-rotate(-28deg) brightness(0.62) contrast(1.05);
}
:root[data-theme="dark"] [data-component="GlobalOmnibar"] svg,
:root[data-theme="dark"] [data-mari-part="home-widget"] svg {
  color: var(--rl-mark);
}
:root[data-theme="dark"] .mari-roleplay-message-row [data-mari-part="avatar"] button {
  box-shadow:
    0 0 0 3px var(--rl-paper-solid),
    0 0 0 5px var(--rl-mark),
    0 0 18px rgba(224, 120, 70, 0.18);
}

/* fog rolls over the chart */
:root[data-theme="light"][data-mari-weather="fog"] {
  --rl-chart: url("theme:chart-fog-day.webp");
}
:root[data-theme="dark"][data-mari-weather="fog"] {
  --rl-chart: url("theme:chart-fog-night.webp");
}
:root[data-mari-weather="fog"] {
  --mari-weather-tint-strength: 1;
}

@media (max-width: 640px) {
  /* the phone chat list fills the screen: no latitude comb against the glass */
  [data-component="ChatSidebar"],
  [data-component="ChatSidebarPanel"],
  [data-component="RightPanelDesktop"] {
    background: var(--sidebar);
    padding-left: 0;
    padding-right: 0;
  }
  /* room under the last position so the rule never hides its frame */
  [data-chat-mode="roleplay"] .mari-messages-scroll {
    padding-bottom: 1.5rem;
  }
}

/* the reply you're answering stays clear of the rule, even while a long draft grows it */
[data-chat-mode="roleplay"] .mari-messages-scroll {
  /* the live rule height plus a four-line reserve, so a growing draft never reaches the reply */
  padding-bottom: calc(var(--mari-roleplay-content-padding-bottom, 96px) + 7rem) !important;
}
[data-chat-mode="conversation"] .mari-messages-scroll {
  padding-bottom: calc(96px + 4.5rem) !important;
}

/* swipe / regenerate: anchored under the slip, on the course side, as a mono log chip */
.ov-rpf--below {
  justify-content: flex-start !important;
  align-self: flex-start !important;
  margin-left: 0 !important;
  font-family: var(--rl-log);
}

/* conversation: keep the current-position frame off the margin scale */
[data-chat-mode="conversation"] [data-mari-part="message"][data-latest] {
  margin-left: 0.75rem;
}

/* Home: the graduated border is kept for the one main inset (Recent chats); the others are
   hairline insets with engraved corner ticks, as a chart's smaller insets are */
[data-home-widget-id]:not([data-home-widget-id="recent"]) [data-mari-part="home-widget"] {
  border-image: none;
  border-width: 1px;
  border-style: solid;
  border-color: var(--rl-ink);
  background:
    linear-gradient(var(--rl-ink), var(--rl-ink)) left 4px top 4px / 10px 1px no-repeat,
    linear-gradient(var(--rl-ink), var(--rl-ink)) left 4px top 4px / 1px 10px no-repeat,
    linear-gradient(var(--rl-ink), var(--rl-ink)) right 4px top 4px / 10px 1px no-repeat,
    linear-gradient(var(--rl-ink), var(--rl-ink)) right 4px top 4px / 1px 10px no-repeat,
    linear-gradient(var(--rl-ink), var(--rl-ink)) left 4px bottom 4px / 10px 1px no-repeat,
    linear-gradient(var(--rl-ink), var(--rl-ink)) left 4px bottom 4px / 1px 10px no-repeat,
    linear-gradient(var(--rl-ink), var(--rl-ink)) right 4px bottom 4px / 10px 1px no-repeat,
    linear-gradient(var(--rl-ink), var(--rl-ink)) right 4px bottom 4px / 1px 10px no-repeat,
    var(--card);
  padding: calc(0.35rem + 7px);
}
@media (max-width: 500px) {
  [data-mari-part="home-widget"] {
    border-image: none !important;
    border: 1px solid var(--rl-ink) !important;
    padding: 0.5rem !important;
    background: var(--card) !important;
  }
}

/* game: the side pane is a chart margin too */
.ov-gpane {
  background:
    linear-gradient(var(--rl-ink), var(--rl-ink)) left 9px top 0 / 1px 100% no-repeat,
    repeating-linear-gradient(180deg, var(--rl-ink) 0 1px, transparent 1px 80px) left 0 top 0 / 9px 100% no-repeat,
    repeating-linear-gradient(180deg, var(--rl-ink) 0 1px, transparent 1px 40px) left 0 top 0 / 6px 100% no-repeat,
    repeating-linear-gradient(180deg, var(--rl-ink) 0 1px, transparent 1px 8px) left 0 top 0 / 3px 100% no-repeat,
    var(--rl-paper-solid) !important;
  border-left: 0 !important;
  padding-left: 12px;
  color: var(--rl-text);
}
.ov-gpane th,
.ov-gpane [class*="uppercase"] {
  font-family: var(--rl-log);
  font-weight: 400;
  letter-spacing: 0.14em;
  color: var(--rl-mark);
}
.ov-gpane__tabs button {
  font-family: var(--rl-serif);
}
.ov-gpane__tabs button.is-on {
  box-shadow: inset 0 -2px 0 var(--rl-mark);
  background: transparent;
}

/* while the log line is pinned it stays a clean log line: its tools come back only when you point at it */
.ov-rpmsg__head:not(:hover):not(:focus-within) .ov-rpf--tools.is-pinned {
  opacity: 0;
  pointer-events: none;
}
.ov-rpmsg__head .ov-rpf--tools {
  background: var(--mari-pinned-speaker-bg);
  border-left: 1px solid var(--rl-hair, var(--border));
  padding-left: 0.4rem;
}

/* Home header: the greeting and its buttons sit on a strip of clear paper, never on the rose or the coast */
.mari-home-hero {
  background: linear-gradient(90deg, transparent, var(--rl-paper-solid) 3%, var(--rl-paper-solid) 97%, transparent);
}
.ov-home-hero-actions .ov-btn {
  background-color: var(--rl-paper-solid);
}
[data-component="CenterContent"] h1.font-black::before {
  text-shadow: 0 0 6px var(--rl-paper-solid), 0 0 12px var(--rl-paper-solid), 0 0 2px var(--rl-paper-solid);
}
/* the swipe chip hangs under the slip's left edge, on the course, never out over the coast */
.ov-rpf.ov-rpf--below.ov-rpf--generate {
  left: 0;
  right: auto;
  width: max-content;
}


/* ================= ROUND 3 ================= */

/* game: the stage is the chart too. A scene picture only tints it faintly from beneath. */
[data-chat-mode="game"] div.bg-cover.inset-0,
:root[data-theme="dark"] [data-chat-mode="game"] div.bg-cover.inset-0 {
  filter: none;
}
[data-chat-mode="game"] div.bg-cover.inset-0::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--rl-chart) center / cover no-repeat, var(--rl-paper-solid);
  opacity: 0.9;
}

/* night: avatars keep their own colour, only warmed by the lamp, so chats stay easy to tell apart */
:root[data-theme="dark"] img:not([data-mari-part="backdrop"]),
:root[data-theme="dark"] [data-mari-part="card-art"] img,
:root[data-theme="dark"] [data-mari-part="avatar-placeholder"] {
  filter: grayscale(0.45) sepia(0.75) saturate(1.5) hue-rotate(-14deg) brightness(0.72) contrast(1.04);
}

/* conversation: a faint paper wash under each line so names never sit on soundings and coast */
[data-chat-mode="conversation"] [data-mari-part="message"] {
  max-width: 76ch;
  background: linear-gradient(90deg,
    color-mix(in srgb, var(--rl-paper-solid) 80%, transparent) 0,
    color-mix(in srgb, var(--rl-paper-solid) 80%, transparent) calc(100% - 5rem),
    transparent 100%);
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-latest] {
  background: var(--rl-paper-solid);
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-latest] {
  margin-left: 1.5rem;
}

/* phone: the current position is a plain hairline, so the reply keeps its width */
@media (max-width: 500px) {
  :root {
    --mari-focus-frame: linear-gradient(var(--rl-ink), var(--rl-ink)) 1 / 1px;
  }
  .mari-roleplay-message-row[data-latest] .mari-rp-bubble,
  [data-chat-mode="conversation"] [data-mari-part="message"][data-latest] {
    border-width: 1px;
  }
}

/* ================= ROUND 4 ================= */
/* Home: the gutters between insets are calm paper, so no stray piece of rose or coast shows between them */
:root:not([data-chat-id]) {
  --mari-app-backdrop-layers:
    linear-gradient(90deg,
      color-mix(in srgb, var(--rl-paper-solid) 45%, transparent) 0,
      color-mix(in srgb, var(--rl-paper-solid) 90%, transparent) 30%,
      color-mix(in srgb, var(--rl-paper-solid) 90%, transparent) 75%,
      color-mix(in srgb, var(--rl-paper-solid) 45%, transparent) 100%),
    var(--rl-chart) center / cover no-repeat,
    var(--rl-paper-solid);
}
